module challenge24 (input clk, input rst_n, input start, input [7:0] val0, input [7:0] val1, input [7:0] val2, input [7:0] val3, output reg [3:0] min_grade, output reg found, output reg done); reg [3:0] min_grade_reg; reg found_reg; reg done_reg; reg [1:0] state; reg [12:0] counter; reg [7:0] val0_reg, val1_reg, val2_reg, val3_reg; always @(posedge clk) begin if (!rst_n) begin min_grade_reg <= 4'd15; found_reg <= 0; done_reg <= 0; state <= 0; counter <= 0; val0_reg <= 0; val1_reg <= 0; val2_reg <= 0; val3_reg <= 0; end else begin if (state == 0) begin if (start) begin val0_reg <= val0; val1_reg <= val1; val2_reg <= val2; val3_reg <= val3; min_grade_reg <= 4'd15; found_reg <= 0; done_reg <= 0; counter <= 0; state <= 1; end end else if (state == 1) begin if (counter < 7680) begin counter <= counter + 1; end else begin state <= 2; end end else if (state == 2) begin end end end end end assign min_grade = min_grade_reg; assign found = found_reg; assign done = done_reg; endmodule